import json
import re
from docx import Document

def fill_offer_letter():
    # Load employee data
    with open('employee_data.json', 'r') as f:
        data = json.load(f)

    doc = Document('offer_letter_template.docx')

    # 1. Handle Conditional Section: {{IF_RELOCATION}}...{{END_IF_RELOCATION}}
    should_include_relocation = data.get('RELOCATION_PACKAGE') == 'Yes'

    start_marker = '{{IF_RELOCATION}}'
    end_marker = '{{END_IF_RELOCATION}}'

    # Find paragraphs with markers
    start_para_idx = -1
    end_para_idx = -1

    for i, para in enumerate(doc.paragraphs):
        if start_marker in para.text:
            start_para_idx = i
        if end_marker in para.text:
            end_para_idx = i

    if start_para_idx != -1 and end_para_idx != -1:
        if should_include_relocation:
            # Keep content, remove markers
            if start_para_idx == end_para_idx:
                # Same paragraph
                para = doc.paragraphs[start_para_idx]
                para.text = para.text.replace(start_marker, '').replace(end_marker, '')
            else:
                # Different paragraphs
                doc.paragraphs[start_para_idx].text = doc.paragraphs[start_para_idx].text.replace(start_marker, '')
                doc.paragraphs[end_para_idx].text = doc.paragraphs[end_para_idx].text.replace(end_marker, '')
        else:
            # Remove the whole section
            # We work backwards to avoid index shifting problems
            for i in range(end_para_idx, start_para_idx - 1, -1):
                p = doc.paragraphs[i]._element
                p.getparent().remove(p)
                p._p = p._element = None

    # 2. Replace placeholders in paragraphs
    def replace_placeholders(paragraphs):
        for para in paragraphs:
            text = para.text
            # Use regex to find all {{KEY}}
            matches = re.findall(r'\{\{([A-Z_]+)\}\}', text)
            if not matches:
                continue

            new_text = text
            for key in matches:
                if key in data:
                    new_text = new_text.replace(f'{{{{{key}}}}}', str(data[key]))

            if new_text != text:
                # Rebuild paragraph to preserve some formatting if possible, 
                # but simple text replacement is safer for split runs.
                # Skill recommends clearing runs and setting text on first run.
                if para.runs:
                    para.runs[0].text = new_text
                    for run in para.runs[1:]:
                        run.text = ''
                else:
                    para.text = new_text

    # Process all paragraphs
    replace_placeholders(doc.paragraphs)

    # Process tables
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                replace_placeholders(cell.paragraphs)

    # Process headers and footers
    for section in doc.sections:
        replace_placeholders(section.header.paragraphs)
        replace_placeholders(section.footer.paragraphs)

    # Save the result
    doc.save('offer_letter_filled.docx')
    print("Offer letter generated successfully: offer_letter_filled.docx")

if __name__ == "__main__":
    fill_offer_letter()

